@startuml

enum BicycleType {
  ROAD
  MOUNTAIN
  BMX
  HYBRID
}

class Client {
  + NIN : string
  + TIN : string
  + name : string
  + address : string
}

class BicycleModel {
  + name : string
  + type : BicycleType
  + gears : int
}

class Bicycle {
  + id : string
}

class Store {
  + name : string
  + address : string
}

class Reservation {
  + pickup_date : date
}

class Rental {
  + return_date : date
}

Client "1" -- "*" Reservation : makes
BicycleModel "1" -- "*" Reservation : requested in
Store "1" -- "*" Reservation : pickup location
Reservation "1" -- "0..1" Rental : becomes
Bicycle "1" -- "0..1" Rental : is rented in
Bicycle "*" -- "1" BicycleModel : is a model of
Bicycle "1" -- "1" Store : stored at
@enduml

